import {taskSwipeAttrs} from './task-swipe.js';
import {taskStatus,setTaskStatus,newId,projectLabel,taskArea,isTaskActive} from './domain.js';
import {recurrenceLabel} from './recurrence.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const statusNames={todo:'Открыта',done:'Выполнена',cancelled:'Отменена'};
export const columnColors={purple:'Фиолетовый',blue:'Синий',green:'Зелёный',orange:'Оранжевый',neutral:'Серый'};
export const defaultBoard=()=>({columns:[{id:'todo',title:'К выполнению',status:'todo',color:'purple'},{id:'doing',title:'В работе',status:'todo',color:'blue'},{id:'done',title:'Выполнено',status:'done',color:'green'},{id:'cancelled',title:'Отменено',status:'cancelled',color:'neutral'}],fields:{project:true,due:true,estimate:false,repeat:true}});
export const boardConfig=(state,scope=null)=>scope?(state.projectBoards?.[scope]||state.kanban||defaultBoard()):(state.kanban||defaultBoard());
export function validateKanban(state){
 if(state.projectBoards!==undefined){if(!state.projectBoards||typeof state.projectBoards!=='object'||Array.isArray(state.projectBoards))throw new Error('Некорректные доски проектов.');for(const [id,config] of Object.entries(state.projectBoards)){if(!state.projects?.some(p=>p.id===id))throw new Error('Не найден проект доски.');validateKanban({...state,projectBoards:undefined,kanban:config});}}
 const b=state.kanban;if(b===undefined)return;
 if(!b||!Array.isArray(b.columns)||b.columns.length<3||b.columns.length>12||!b.fields||typeof b.fields!=='object')throw new Error('Некорректная Kanban-доска.');
 const ids=new Set();for(const c of b.columns){if(!c||typeof c.id!=='string'||!c.id||c.id.length>250||ids.has(c.id)||typeof c.title!=='string'||!c.title.trim()||c.title.length>60||!Object.hasOwn(statusNames,c.status)||!Object.hasOwn(columnColors,c.color))throw new Error('Проверьте названия и статусы колонок.');ids.add(c.id);}
 for(const status of Object.keys(statusNames))if(!b.columns.some(c=>c.status===status))throw new Error('Нужна хотя бы одна колонка каждого статуса: открыта, выполнена и отменена.');
 for(const key of ['project','due','estimate','repeat'])if(typeof b.fields[key]!=='boolean')throw new Error('Некорректные поля карточек.');
 for(const t of state.tasks)if(t.kanbanColumnId!=null&&typeof t.kanbanColumnId!=='string'||t.kanbanOrder!==undefined&&(!Number.isFinite(t.kanbanOrder)||t.kanbanOrder<0))throw new Error('Некорректная позиция карточки.');
}
export function taskColumn(state,t,scope=null){const b=boardConfig(state,scope),status=taskStatus(t);return b.columns.find(c=>c.id===t.kanbanColumnId&&c.status===status)||b.columns.find(c=>c.status===status);}
export function applyBoard(state,config,scope=null){
 const copy=JSON.parse(JSON.stringify(config));validateKanban({...state,projectBoards:undefined,kanban:copy});if(scope){state.projectBoards??={};state.projectBoards[scope]=copy;}else state.kanban=copy;
 for(const t of state.tasks)if((!scope||t.projectId===scope)&&!copy.columns.some(c=>c.id===t.kanbanColumnId&&c.status===taskStatus(t)))t.kanbanColumnId=null;
}
export function moveKanbanTask(state,id,columnId,date,beforeId=null,idFactory=newId,scope=null){
 const task=state.tasks.find(t=>t.id===id),column=boardConfig(state,scope).columns.find(c=>c.id===columnId);
 if(!task||!isTaskActive(state,task)||!column||scope&&task.projectId!==scope)throw new Error('Задача или колонка недоступна.');
 const next=taskStatus(task)!==column.status?setTaskStatus(state,id,column.status,date,idFactory):null;
 task.kanbanColumnId=column.id;
 const siblings=state.tasks.filter(t=>isTaskActive(state,t)&&t.id!==id&&(!scope||t.projectId===scope)&&taskColumn(state,t,scope)?.id===column.id).sort((a,b)=>(a.kanbanOrder??1e9)-(b.kanbanOrder??1e9));
 const at=beforeId?siblings.findIndex(t=>t.id===beforeId):-1;siblings.splice(at<0?siblings.length:at,0,task);siblings.forEach((t,i)=>t.kanbanOrder=i);
 return next;
}
export function taskViewToggle(layout){return `<div class="habit-view-toggle" role="group" aria-label="Вид задач"><button data-action="task-view" data-view="table" aria-pressed="${layout!=='kanban'}">☷ <span>Список</span></button><button data-action="task-view" data-view="kanban" aria-pressed="${layout==='kanban'}">▥ <span>Kanban</span></button></div>`;}
export function kanbanHTML(state,tasks,scope=null){
 const b=boardConfig(state,scope),someday=tasks.filter(t=>t.someday);tasks=tasks.filter(t=>!t.someday);
 return `<div class="kanban-toolbar"><span>Задач: ${tasks.length}</span><button class="secondary-button" data-action="configure-kanban">⚙ Настроить доску</button></div><div class="kanban-board" aria-label="Kanban задач">${b.columns.map(col=>{const items=tasks.filter(t=>taskColumn(state,t,scope)?.id===col.id).sort((a,b)=>(a.kanbanOrder??1e9)-(b.kanbanOrder??1e9));return `<section class="kanban-column" data-drop-column="${esc(col.id)}" data-color="${col.color}" aria-label="${esc(col.title)}"><div class="kanban-column-heading"><h2><i></i>${esc(col.title)}</h2><span class="count">${items.length}</span></div><div class="kanban-cards">${items.map(t=>{const area=state.areas.find(a=>a.id===taskArea(state,t));return `<article class="kanban-card" draggable="${!t.archived}" data-drag-task="${esc(t.id)}" data-drag-source="kanban" data-card-id="${esc(t.id)}" ${taskSwipeAttrs(state,t)}><div class="kanban-card-title"><span class="drag-grip" aria-hidden="true">⠿</span><button class="task-title ${t.done?'completed':''}" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button></div>${b.fields.project&&(t.projectId||area)?`<div class="kanban-card-meta">${esc(projectLabel(state,t.projectId)||area?.name||'')}</div>`:''}<div class="kanban-card-details">${b.fields.due&&t.due?`<span>${new Date(t.due+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'})}</span>`:''}${b.fields.estimate&&t.estimate?`<span>${t.estimate} ч</span>`:''}${b.fields.repeat&&t.recurrence!=='none'?`<span>↻ ${esc(recurrenceLabel(t))}</span>`:''}</div><label class="kanban-move"><span class="visually-hidden">Переместить: ${esc(t.title)}</span><select data-kanban-move="${esc(t.id)}" aria-label="Колонка: ${esc(t.title)}" ${t.archived?'disabled':''}>${b.columns.map(c=>`<option value="${esc(c.id)}" ${c.id===col.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label></article>`;}).join('')||'<div class="kanban-empty">Перетащите задачу сюда</div>'}</div></section>`;}).join('')}</div>${someday.length?`<details class="flow-section kanban-someday" open><summary>Когда-нибудь <span class="count">${someday.length}</span></summary><div class="flow-section-body">${someday.map(t=>`<div class="picker-task"><button class="task-title" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button><button class="text-button" data-action="activate-task" data-id="${esc(t.id)}">В работу</button></div>`).join('')}</div></details>`:''}`;
}
export function boardSettingsHTML(b){return `<h2>Настроить Kanban</h2><p class="modal-description">Названия, порядок и цвет колонок. Статус определяет, считается ли задача выполненной.</p><form id="kanban-settings-form"><div class="kanban-settings-columns">${b.columns.map((c,i)=>`<div class="kanban-settings-row" data-column-index="${i}"><input class="field" data-column-field="title" aria-label="Название колонки ${i+1}" maxlength="60" required value="${esc(c.title)}"><select class="field" data-column-field="status" aria-label="Статус колонки ${i+1}">${Object.entries(statusNames).map(([v,l])=>`<option value="${v}" ${v===c.status?'selected':''}>${l}</option>`).join('')}</select><select class="field" data-column-field="color" aria-label="Цвет колонки ${i+1}">${Object.entries(columnColors).map(([v,l])=>`<option value="${v}" ${v===c.color?'selected':''}>${l}</option>`).join('')}</select><div class="kanban-column-actions"><button type="button" data-action="kanban-column-up" data-index="${i}" aria-label="Колонку ${i+1} выше" ${i===0?'disabled':''}>↑</button><button type="button" data-action="kanban-column-down" data-index="${i}" aria-label="Колонку ${i+1} ниже" ${i===b.columns.length-1?'disabled':''}>↓</button><button type="button" data-action="kanban-column-remove" data-index="${i}" aria-label="Убрать колонку ${i+1}">×</button></div></div>`).join('')}</div><button class="text-button" type="button" data-action="kanban-column-add" ${b.columns.length>=12?'disabled':''}>+ Колонка</button><fieldset class="kanban-field-settings"><legend>Поля карточки</legend>${Object.entries({project:'Проект или зона',due:'Срок',estimate:'Оценка времени',repeat:'Повторение'}).map(([k,v])=>`<label><input type="checkbox" data-board-field="${k}" ${b.fields[k]?'checked':''}> ${v}</label>`).join('')}</fieldset><div id="kanban-error" class="error-text" role="alert"></div><div class="modal-actions"><button type="button" class="secondary-button" data-action="close-modal">Отмена</button><button type="submit" class="primary-button">Сохранить доску</button></div></form>`;}
